import * as net from 'node:net';
import process from 'node:process';
function main(): void {
  const srv = net.createServer((s: any) => { s.end('x'); });
  process.on('unhandledRejection', (): void => { console.log('h'); srv.close(); });
  srv.listen(0, '127.0.0.1', (): void => { Promise.reject(new Error('x')); });
}
